PRAGMA foreign_keys = ON;
CREATE TABLE users (id INTEGER PRIMARY KEY, created_at INTEGER NOT NULL);
CREATE TABLE user_settings (user_id INTEGER PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, timezone TEXT NOT NULL DEFAULT 'UTC', language TEXT NOT NULL DEFAULT 'en' CHECK(language IN ('en','ru')), reminders_enabled INTEGER NOT NULL DEFAULT 1 CHECK(reminders_enabled IN (0,1)), state TEXT, state_expires INTEGER, rate_window INTEGER NOT NULL DEFAULT 0, rate_count INTEGER NOT NULL DEFAULT 0);
CREATE TABLE notes (id TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, title TEXT NOT NULL, content TEXT NOT NULL CHECK(length(content)<=4000), category TEXT NOT NULL DEFAULT 'Inbox', archived INTEGER NOT NULL DEFAULT 0 CHECK(archived IN (0,1)), pinned INTEGER NOT NULL DEFAULT 0 CHECK(pinned IN (0,1)), created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, UNIQUE(id,user_id));
CREATE INDEX notes_owner_recent ON notes(user_id,archived,pinned,created_at);
CREATE INDEX notes_owner_category ON notes(user_id,category);
CREATE INDEX notes_owner_updated ON notes(user_id,updated_at);
CREATE VIRTUAL TABLE notes_fts USING fts5(title,content,content='notes',content_rowid='rowid');
CREATE TRIGGER notes_ai AFTER INSERT ON notes BEGIN INSERT INTO notes_fts(rowid,title,content) VALUES(new.rowid,new.title,new.content); END;
CREATE TRIGGER notes_ad AFTER DELETE ON notes BEGIN INSERT INTO notes_fts(notes_fts,rowid,title,content) VALUES('delete',old.rowid,old.title,old.content); END;
CREATE TRIGGER notes_au AFTER UPDATE ON notes BEGIN INSERT INTO notes_fts(notes_fts,rowid,title,content) VALUES('delete',old.rowid,old.title,old.content); INSERT INTO notes_fts(rowid,title,content) VALUES(new.rowid,new.title,new.content); END;
CREATE TABLE tags (id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, name TEXT NOT NULL, UNIQUE(user_id,name), UNIQUE(id,user_id));
CREATE TABLE note_tags (note_id TEXT NOT NULL, tag_id INTEGER NOT NULL, user_id INTEGER NOT NULL, PRIMARY KEY(note_id,tag_id), FOREIGN KEY(note_id,user_id) REFERENCES notes(id,user_id) ON DELETE CASCADE, FOREIGN KEY(tag_id,user_id) REFERENCES tags(id,user_id) ON DELETE CASCADE);
CREATE INDEX note_tags_owner ON note_tags(user_id,tag_id);
CREATE TABLE tasks (id TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, title TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','completed')), priority TEXT NOT NULL DEFAULT 'normal' CHECK(priority IN ('low','normal','high')), due_at INTEGER, note_id TEXT REFERENCES notes(id) ON DELETE SET NULL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, completed_at INTEGER);
CREATE INDEX tasks_owner_status_due ON tasks(user_id,status,due_at);
CREATE TABLE reminders (id TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, content TEXT NOT NULL, note_id TEXT REFERENCES notes(id) ON DELETE SET NULL, due_at INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','sending','delivered','failed','cancelled','dismissed')), attempts INTEGER NOT NULL DEFAULT 0, next_attempt INTEGER NOT NULL, lease_until INTEGER, lease_token TEXT, last_error TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, delivered_at INTEGER);
CREATE INDEX reminders_due ON reminders(status,next_attempt);
CREATE INDEX reminders_owner ON reminders(user_id,due_at);
CREATE TABLE vocabulary (id TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, word TEXT NOT NULL, definition TEXT NOT NULL DEFAULT '', example TEXT NOT NULL DEFAULT '', translation TEXT NOT NULL DEFAULT '', created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE INDEX vocabulary_owner ON vocabulary(user_id,created_at);
CREATE TABLE vocabulary_tags (vocabulary_id TEXT NOT NULL REFERENCES vocabulary(id) ON DELETE CASCADE, tag_id INTEGER NOT NULL REFERENCES tags(id) ON DELETE CASCADE, PRIMARY KEY(vocabulary_id,tag_id));
CREATE TABLE webhook_events (update_id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL, created_at INTEGER NOT NULL, reply TEXT NOT NULL, delivered INTEGER NOT NULL DEFAULT 0);
CREATE INDEX webhook_retention ON webhook_events(created_at);
